// Per-spot radar time series, generated by scripts/spot_timeseries.py from the public NISAR TIFs
// (data/wet_spots/spot_timeseries.json, no pipe geometry). Bundled at build time, so the card works offline.
import raw from "../../../data/wet_spots/spot_timeseries.json";

export type ByDate = Record<string, number | null>;
export type SpotSeries = {
  spot_id: string;
  lat: number;
  lon: number;
  pixel: { col: number; row: number };
  window_100m: { hh_db: ByDate; hv_db: ByDate; hh_change_db: ByDate; hv_change_db: ByDate; px: number };
  wet_pixels: { px: number; area_m2: number; centroid_offset_m: number; hh_db: ByDate; hv_db: ByDate; hh_change_db: ByDate; hv_change_db: ByDate };
  wet_px_within_100m: number;
  crop: {
    png_px: { x: number; y: number; w: number; h: number };
    spot_in_crop_px: { x: number; y: number };
    m_per_px: { x: number; y: number };
    size_m: { x: number; y: number };
    lonlat: { west: number; east: number; north: number; south: number };
    inside_grid_frac: number;
    wet_cells: [number, number][];
  };
};
export type SeriesFile = {
  passes: string[];
  baseline: string;
  thresholds_db: { hh: number; hv: number };
  params: { window_px: number; window_m: number; radius_m: number; crop_px: number; crop_m: number };
  grid: { bounds: { west: number; south: number; east: number; north: number }; size_px: [number, number]; m_per_px: number };
  images: { before: string; after: string };
  spots: SpotSeries[];
  source: string;
};

export const SERIES = raw as unknown as SeriesFile;

export function seriesFor(id: string | null | undefined): SpotSeries | null {
  if (!id) return null;
  return SERIES.spots.find((s) => s.spot_id.toUpperCase() === id.toUpperCase()) ?? null;
}
